/* ---------------------------------------------------------------------
   Pass phrase gate — wired up first, before anything else, so it works
   even if a later part of the app throws an error.
--------------------------------------------------------------------- */
(function(){
  const PASS_PHRASE = 'applied';
  const form = document.getElementById('gateForm');
  const passInput = document.getElementById('gatePass');
  const err = document.getElementById('gateError');

  // Health-check test mode (25-09-2026) — skips the gate ONLY when the page
  // is actually being served from localhost/127.0.0.1. This reads the real,
  // browser-supplied location.hostname; there is no query param, cookie, or
  // localStorage flag involved anywhere, so nothing set from outside this
  // page (a URL someone shares, a bookmarklet, devtools on the live site)
  // can ever trigger it. On the deployed origin (appliedconceptsnl.github.io),
  // location.hostname can never equal "localhost" or "127.0.0.1" — this
  // branch is structurally unreachable there, not just "off by default".
  // Used by the Playwright health check (see /healthcheck) to drive the
  // full app without the pass phrase; the live site's gate is unaffected
  // and still tested separately, from the outside, in that same check.
  if(location.hostname === 'localhost' || location.hostname === '127.0.0.1'){
    document.body.classList.add('unlocked');
    setTimeout(refitAllPreviews, 0);
  }

  form.addEventListener('submit', function(e){
    e.preventDefault();
    const val = (passInput.value || '').trim().toLowerCase();
    if(val === PASS_PHRASE){
      document.body.classList.add('unlocked');
      err.textContent = '';
      // Layout was hidden (display:none) until now, so previews computed
      // during initial load may have a bogus scale — recompute for real.
      setTimeout(refitAllPreviews, 0);
    } else {
      err.textContent = 'Onjuiste pass phrase — probeer opnieuw.';
      passInput.value = '';
      passInput.focus();
    }
  });
  passInput.focus();
})();

/* ---------------------------------------------------------------------
   "Vraag pass phrase aan" — for someone who has the installed app but no
   pass phrase yet. Goes straight to WhatsApp with just "Verzoek pass
   phrase" — deliberately no naam/eenheid/functie template (22-09-2026:
   "ik hoef geen verdere info, als ik die wil kan ik er zelf om vragen").
   The pass phrase itself is never sent automatically, that's still a
   manual reply. Reuses SHOP_WHATSAPP_NUMBER (js/shop.js, loaded before
   this script) — same real-world contact, no reason to duplicate the
   number.
--------------------------------------------------------------------- */
(function(){
  const btn = document.getElementById('gateRequestBtn');
  if(!btn) return;
  btn.addEventListener('click', function(){
    const message = 'Verzoek pass phrase';
    const url = `https://wa.me/${SHOP_WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank', 'noopener');
  });
})();

