// Average NATO-standard 5.56x45mm ammunition (M855A1 62gr EPR reference —
// current US/NATO service load) per platform's typical barrel length, used
// ONLY for the "kogelbaan"-info block below (22-09-2026, on request: "altijd
// de gemiddelde waarde en op basis van NATO standaard munitie"). This is
// published/typical data, NOT a chronographed measurement of the user's own
// rifle — real drop varies with the actual ammo lot, barrel and conditions.
// '416' has no documented length in OPTIC_PLATFORMS above; treated here as
// the other common short HK416 configuration (11") alongside the explicit
// 14.5" entry. MCX Rattler is normally a .300 BLK-first platform, but is
// kept in 5.56 NATO here for a consistent "NATO standard" framing across
// every platform, at its much shorter ~6.75" barrel.
const OPTIC_PLATFORM_AMMO = {
  '416':         { caliber:'5.56×45mm NATO — 11", M855A1 62gr (gem.)', bulletWeightGr:62, muzzleVelocityFps:2750, bc:0.304, dragModel:'G1' },
  '416_145':     { caliber:'5.56×45mm NATO — 14.5", M855A1 62gr (gem.)', bulletWeightGr:62, muzzleVelocityFps:2920, bc:0.304, dragModel:'G1' },
  'mcx_virtus':  { caliber:'5.56×45mm NATO — 16", M855A1 62gr (gem.)', bulletWeightGr:62, muzzleVelocityFps:2970, bc:0.304, dragModel:'G1' },
  'mcx_rattler': { caliber:'5.56×45mm NATO — 6.75", M855A1 62gr (gem.)', bulletWeightGr:62, muzzleVelocityFps:2300, bc:0.304, dragModel:'G1' },
};

function populateSelect(sel, items, fmt){
  sel.innerHTML = items.map((v,i)=>`<option value="${i}">${fmt(v)}</option>`).join('');
}

function fmtLen(inches, unit){
  if(unit === 'in') return inches.toFixed(2) + '"';
  return (inches/CM_IN).toFixed(2) + ' cm';
}

function offsetAxis(valueIn, zeroDist, workDist){
  if(workDist >= zeroDist) return 0;
  return valueIn * (1 - workDist/zeroDist);
}

// The calculator always clamps workDist to zeroDist for the actual math (see
// getStateOptic) so a "controle-afstand > nulpunt" combo can
// never break the geometry — but the <select> itself allowed picking one
// anyway, and once picked the marker just silently drops out (off becomes 0,
// so showMarker is false) with the dropdown still showing the too-large
// value. That reads as "the POI just disappeared" with no explanation.
// Filter the controle-afstand options down to "<= nulpunt" so the invalid
// combo can't be selected in the first place, from either select.
function refreshWorkDistOptions(distArray, zeroSelId, workSelId){
  const zeroDist = distArray[el(zeroSelId).value];
  const workSel = el(workSelId);
  const prevWorkDist = distArray[workSel.value];
  const allowed = distArray.filter(d => d <= zeroDist);
  populateSelect(workSel, allowed, d=>d+' m');
  const idx = allowed.indexOf(prevWorkDist);
  workSel.selectedIndex = idx !== -1 ? idx : allowed.length-1;
}

function clickSizeIn(clickVal, adjUnit, dist){
  if(adjUnit === 'MOA'){
    return clickVal * 2.908 * (dist/100) * CM_IN; // 1 MOA ~ 2.908 cm @ 100 m
  } else {
    return clickVal * 10 * (dist/100) * CM_IN; // 1 mil = 10 cm @ 100 m
  }
}

/* ---------------------------------------------------------------------
   Print/preview engine — used by the Optic Calculator. Was also shared with
   the Zero Laser Calculator, archived on 18-09-2026 (see
   archive/zero-laser-calculator/) — keep this generic enough to still fit
   that tab if it comes back.
--------------------------------------------------------------------- */

function drawFrame(cx, cy, S, FT, dot){
  const half = S/2;
  let g = `<g>`;
  g += `<path d="M${(cx-half).toFixed(4)},${(cy-half).toFixed(4)}
    h${S.toFixed(4)} v${S.toFixed(4)} h${(-S).toFixed(4)} Z
    M${(cx-half+FT).toFixed(4)},${(cy-half+FT).toFixed(4)}
    h${(S-2*FT).toFixed(4)} v${(S-2*FT).toFixed(4)} h${(-(S-2*FT)).toFixed(4)} Z"
    fill="#171510" fill-rule="evenodd"/>`;
  g += `<rect x="${(cx-dot/2).toFixed(4)}" y="${(cy-dot/2).toFixed(4)}" width="${dot.toFixed(4)}" height="${dot.toFixed(4)}" fill="#171510"/>`;
  g += `<text x="${cx.toFixed(4)}" y="${(cy+dot/2+0.16).toFixed(4)}" text-anchor="middle" font-size="0.13" font-weight="600" fill="#171510" font-family="IBM Plex Mono, monospace">POA</text>`;
  g += `</g>`;
  return g;
}

function buildTable(clickVal, adjUnit, gridIn, distOptions, distUnit, x, y, w){
  const dists = distOptions;
  const colW = w/ (dists.length+1);
  let g = `<g font-family="IBM Plex Mono, monospace" fill="#171510">`;
  g += `<line x1="${x}" y1="${(y-0.14).toFixed(4)}" x2="${x+w}" y2="${(y-0.14).toFixed(4)}" stroke="#171510" stroke-width="0.012"/>`;
  g += `<text x="${x}" y="${y.toFixed(4)}" font-size="0.13" font-family="Oswald, sans-serif" font-weight="600">KLIKTABEL — ${clickVal} ${adjUnit} PER KLIK</text>`;
  const headerY = y+0.24;
  g += `<text x="${x}" y="${headerY.toFixed(4)}" font-size="0.12">Afstand</text>`;
  dists.forEach((d,i)=>{
    g += `<text x="${(x+colW*(i+1)).toFixed(4)}" y="${headerY.toFixed(4)}" font-size="0.12">${d} ${distUnit}</text>`;
  });
  g += `<line x1="${x}" y1="${(headerY+0.08).toFixed(4)}" x2="${x+w}" y2="${(headerY+0.08).toFixed(4)}" stroke="#8f8f8a" stroke-width="0.006"/>`;
  // Just the one number a shooter actually dials: clicks per whole grid
  // square, per distance. "Vakjes per klik" (the inverse, fractional-square
  // framing) and the "1 vakje = X cm" caption were both dropped — neither
  // is the answer you're reading this table on the range for.
  const row1Y = headerY+0.26;
  g += `<text x="${x}" y="${row1Y.toFixed(4)}" font-size="0.12">Klikken per vakje</text>`;
  dists.forEach((d,i)=>{
    const sizeIn = clickSizeIn(clickVal, adjUnit, d);
    const clicksPerSquare = (gridIn/sizeIn).toFixed(2);
    g += `<text x="${(x+colW*(i+1)).toFixed(4)}" y="${row1Y.toFixed(4)}" font-size="0.12">${clicksPerSquare} klik</text>`;
  });
  g += `</g>`;
  return g;
}

// Compact "kogelbaan"-info block, printed beside the QR code — where the
// true (gravity-drop) trajectory crosses the line of sight the 2nd time
// downrange of the zero itself (the 1st crossing, trivially), plus the drop
// and retained energy 100 m past that 2nd crossing. Only rendered when a
// Wapenplatform preset is selected (see OPTIC_PLATFORM_AMMO) — average NATO-
// standard ammunition data, not measured for the user's specific rifle.
function buildTrajectoryBlock(x, y, w, traj, caliber){
  let g = `<g font-family="IBM Plex Mono, monospace" fill="#171510">`;
  g += `<text x="${x}" y="${(y+0.13).toFixed(4)}" font-size="0.11" font-family="Oswald, sans-serif" font-weight="600">KOGELBAAN — ${caliber}</text>`;
  g += `<text x="${x}" y="${(y+0.30).toFixed(4)}" font-size="0.105">1e kruispunt (inschiet): ${traj.nearZeroM} m &#183; 2e kruispunt: ${traj.farZeroM.toFixed(0)} m</text>`;
  g += `<text x="${x}" y="${(y+0.47).toFixed(4)}" font-size="0.105">Drop @ +100 m na 2e kruispunt: ${traj.dropCm.toFixed(0)} cm &#183; Energie daar: ${traj.energyJAtTarget.toFixed(0)} J (${traj.energyFtLbsAtTarget.toFixed(0)} ft-lbs)</text>`;
  g += `<text x="${x}" y="${(y+0.60).toFixed(4)}" font-size="0.085" fill="#8f8f8a">Gemiddelde NATO-standaardmunitie — geen gemeten data voor dit exemplaar.</text>`;
  g += `</g>`;
  return g;
}

function buildTargetSVG(cfg){
  const P = cfg.paper;
  const W = P.w, H = P.h;
  const MARGIN = 0.22;
  // Header text is a single left-hand column now (see below) — Wapen and
  // Datum used to share a row with Richtmiddel/Montage via a second column
  // at W/2, but that column is where the big top-right logo lives now, so
  // every meta line gets its own row instead. Count them up so the header
  // (and the grid below it) sizes itself to whatever cfg actually has.
  let metaLineCount = 2; // Wapen + Datum
  cfg.metaRows.forEach(row => { metaLineCount += row[1] ? 2 : 1; });
  const metaFirstY = 0.68, metaLineH = 0.18;
  const metaLastY = metaFirstY + (metaLineCount-1)*metaLineH;
  const HEADER_H = metaLastY + (cfg.instructionLine ? 0.22 : 0) + 0.30, FOOTER_H = 1.55;
  const gridTop = HEADER_H, gridBottom = H - FOOTER_H;
  const gridLeft = MARGIN, gridRight = W - MARGIN;
  const cx = W/2;
  const targetCy = gridTop + (gridBottom-gridTop)*0.40;

  const S = 16*CM_IN;
  const FT = cfg.gridIn*2;
  const dot = cfg.gridIn*0.8;
  const pad = cfg.gridIn*3;

  let svg = `<svg viewBox="0 0 ${W} ${H}" width="${W}in" height="${H}in" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">`;
  svg += `<rect x="0" y="0" width="${W}" height="${H}" fill="var(--paper)"/>`;

  svg += `<g stroke="#d8d8d2" stroke-width="0.006">`;
  for(let x=gridLeft; x<=gridRight+0.001; x+=cfg.gridIn){
    svg += `<line x1="${x.toFixed(4)}" y1="${gridTop}" x2="${x.toFixed(4)}" y2="${gridBottom}"/>`;
  }
  for(let y=gridTop; y<=gridBottom+0.001; y+=cfg.gridIn){
    svg += `<line x1="${gridLeft}" y1="${y.toFixed(4)}" x2="${gridRight}" y2="${y.toFixed(4)}"/>`;
  }
  svg += `</g>`;

  svg += `<g stroke="#171510" stroke-width="0.012">
    <line x1="${cx}" y1="${gridTop}" x2="${cx}" y2="${gridBottom}"/>
    <line x1="${gridLeft}" y1="${targetCy}" x2="${gridRight}" y2="${targetCy}"/>
  </g>`;

  const qfs = 0.16;
  svg += `<g fill="#8f8f89" font-size="${qfs}" font-family="IBM Plex Mono, monospace">
    <text x="${gridLeft+0.15}" y="${targetCy-0.2}">R/D</text>
    <text x="${gridRight-0.55}" y="${targetCy-0.2}">L/D</text>
    <text x="${gridLeft+0.15}" y="${targetCy+0.35}">R/U</text>
    <text x="${gridRight-0.55}" y="${targetCy+0.35}">L/U</text>
  </g>`;

  svg += drawFrame(cx, targetCy, S, FT, dot);

  const markerBS = cfg.gridIn*4.2;
  let anyFits = true;
  (cfg.markers || []).forEach(m=>{
    if(!m.show) return;
    const mMag = Math.hypot(m.offX, m.offY);
    const mCx = cx + m.offX, mCy = targetCy + m.offY;
    const mFits = (mCx - pad) > gridLeft && (mCx + pad) < gridRight && (mCy + pad) < gridBottom;
    if(!mFits){ anyFits = false; return; }
    const dirLen = Math.max(mMag, 0.0001);
    const ux = m.offX/dirLen, uy = m.offY/dirLen;
    const startX = cx + ux*(S/2), startY = targetCy + uy*(S/2);
    const endX = mCx - ux*(markerBS/2), endY = mCy - uy*(markerBS/2);

    // POI marker uses the gold accent instead of the frame's ink color — the
    // black square frame/POA dot sit at the same coordinates the marker is
    // drawn relative to, and near the zero distance the offset is small
    // enough that the marker can land partly inside the black frame itself.
    // A near-black-on-black marker there would be unreadable.
    const markerColor = '#c9a35c';
    svg += `<rect x="${(mCx-markerBS/2).toFixed(4)}" y="${(mCy-markerBS/2).toFixed(4)}" width="${markerBS.toFixed(4)}" height="${markerBS.toFixed(4)}"
      fill="none" stroke="${markerColor}" stroke-width="0.026" stroke-dasharray="0.06,0.05"/>`;
    svg += `<circle cx="${mCx.toFixed(4)}" cy="${mCy.toFixed(4)}" r="${(cfg.gridIn*0.18).toFixed(4)}" fill="${markerColor}"/>`;
    svg += `<line x1="${startX.toFixed(4)}" y1="${startY.toFixed(4)}" x2="${endX.toFixed(4)}" y2="${endY.toFixed(4)}" stroke="${markerColor}" stroke-width="0.013"/>`;
    svg += `<text x="${mCx.toFixed(4)}" y="${(mCy+markerBS/2+0.16).toFixed(4)}" text-anchor="middle" font-size="0.13" font-weight="700" fill="${markerColor}" font-family="IBM Plex Mono, monospace">${m.label}</text>`;
    if(m.detail) svg += `<text x="${mCx.toFixed(4)}" y="${(mCy+markerBS/2+0.33).toFixed(4)}" text-anchor="middle" font-size="0.11" fill="#6e6e6a">${m.detail}</text>`;
  });
  const anyShown = (cfg.markers || []).some(m=>m.show);
  if(!anyShown && cfg.sameDistanceCaption){
    svg += `<text x="${cx.toFixed(4)}" y="${(targetCy+S/2+0.28).toFixed(4)}" text-anchor="middle" font-size="0.14" fill="#6e6e6a">${cfg.sameDistanceCaption}</text>`;
  }

  if(!anyFits && anyShown){
    svg += `<text x="${cx.toFixed(4)}" y="${(gridBottom-0.15).toFixed(4)}" text-anchor="middle" font-size="0.15" fill="#c9573f">
      Let op: één of meer offsets vallen buiten dit papierformaat — zie waarschuwing links</text>`;
  }

  // Big top-right logo, reaching almost down to the grid — the meta text
  // used to share a second column at W/2 with the logo's old, much
  // smaller footprint; that column is entirely the logo's now, so every
  // meta line below got its own row (see metaLineCount above) instead of
  // pairing up two-per-row. textRight is how far those lines (and the
  // shortened divider) are allowed to run before they'd hit the logo.
  const logoTop = 0.14, logoBottom = HEADER_H - 0.12;
  const logoBandH = logoBottom - logoTop;
  const logoH = logoBandH * SHEET_LOGO_SCALE, logoW = logoH*LOGO_ASPECT;
  const logoY = logoTop + (logoBandH-logoH)/2;
  const logoX = W - MARGIN - logoW;
  const textRight = logoX - 0.25;
  svg += `<svg x="${logoX.toFixed(4)}" y="${logoY.toFixed(4)}" width="${logoW.toFixed(4)}" height="${logoH.toFixed(4)}" viewBox="${LOGO_VIEWBOX}">${LOGO_BLACK_INNER}</svg>`;

  let headerSvg = `<g font-family="IBM Plex Mono, monospace" fill="#171510">
    <text x="${MARGIN}" y="0.24" font-size="0.19" font-family="Oswald, sans-serif" font-weight="600">${cfg.titleMain}</text>
    <text x="${MARGIN}" y="0.40" font-size="0.10" letter-spacing="0.01" fill="#6e6e6a">APPLIED CONCEPTS — PERFORMANCE · DEVELOPMENT</text>
    <line x1="${MARGIN}" y1="0.50" x2="${textRight.toFixed(4)}" y2="0.50" stroke="#171510" stroke-width="0.012"/>
    <text x="${MARGIN}" y="${metaFirstY.toFixed(4)}" font-size="0.13">Wapen: ${cfg.weaponLabel || '________________________'}</text>
    <text x="${MARGIN}" y="${(metaFirstY+metaLineH).toFixed(4)}" font-size="0.13">Datum: ${new Date().toLocaleDateString('nl-NL')}</text>`;
  let metaY = metaFirstY + 2*metaLineH;
  cfg.metaRows.forEach(row=>{
    headerSvg += `<text x="${MARGIN}" y="${metaY.toFixed(4)}" font-size="0.13">${row[0]}</text>`;
    metaY += metaLineH;
    if(row[1]){
      headerSvg += `<text x="${MARGIN}" y="${metaY.toFixed(4)}" font-size="0.13">${row[1]}</text>`;
      metaY += metaLineH;
    }
  });
  if(cfg.instructionLine){
    headerSvg += `<text x="${MARGIN}" y="${(metaY+0.12).toFixed(4)}" font-size="0.13" font-weight="600">${cfg.instructionLine}</text>`;
  }
  headerSvg += `</g>`;
  svg += headerSvg;

  svg += buildTable(cfg.clickVal, cfg.adjUnit, cfg.gridIn, cfg.distOptions, cfg.distUnit, MARGIN, H-FOOTER_H+0.22, W-2*MARGIN);

  svg += `<text x="${(W-MARGIN).toFixed(4)}" y="${(H-0.14).toFixed(4)}" text-anchor="end" font-size="0.10" fill="#8f8f8a" font-family="IBM Plex Mono, monospace">${cfg.footerRight}</text>`;

  // QR in the corner below the click table — scans straight to the app.
  // Sized to actually stand out and invite a scan (not just be technically
  // present); the one-row click table above frees up enough of the
  // reserved footer height to fit it without touching FOOTER_H.
  const qrSize = 0.6;
  svg += buildAppQrSvg(MARGIN, H-0.1-qrSize, qrSize);

  if(cfg.trajectory){
    const trajX = MARGIN + qrSize + 0.25;
    svg += buildTrajectoryBlock(trajX, H-0.1-qrSize, (W-MARGIN)-trajX, cfg.trajectory, cfg.trajectoryCaliber);
  } else if(cfg.trajectoryNote){
    // Shorter than the on-screen version (cfg.trajectoryNote) — this has to
    // fit on one printed line next to the QR code instead of wrapping.
    const trajX = MARGIN + qrSize + 0.25;
    const shortNote = cfg.trajectoryNote.includes('HOB in')
      ? 'Vul de HOB in om de kogelbaan te berekenen.'
      : 'Kogelbaan: geen 2e kruispunt binnen bereik voor dit nulpunt/HOB.';
    svg += `<text x="${trajX.toFixed(4)}" y="${(H-0.1-qrSize+0.2).toFixed(4)}" font-size="0.1" fill="#8f8f8a" font-family="IBM Plex Mono, monospace">${shortNote}</text>`;
  }

  svg += `</svg>`;
  return { svg, fitsOnPage: anyFits, anyShown };
}

function fitPreview(pageId, shellId, labelId){
  const pageEl = el(pageId);
  const shell = el(shellId);
  const container = pageEl.closest('.preview');
  const naturalW = parseFloat(pageEl.style.width)*96 || pageEl.offsetWidth || 794;
  const naturalH = parseFloat(pageEl.style.height)*96 || pageEl.offsetHeight || 1123;
  // container.clientWidth reads as 0 while the app is hidden behind the gate
  // (display:none) or otherwise not yet laid out — guard against that so we
  // never compute a negative/zero scale.
  const rawAvailW = container.clientWidth - 52;
  const availW = rawAvailW > 100 ? rawAvailW : naturalW;
  const rawAvailH = window.innerHeight - 160;
  const availH = rawAvailH > 100 ? rawAvailH : naturalH;
  const scale = Math.min(1, availW/naturalW, availH/naturalH);
  pageEl.style.transformOrigin = 'top left';
  pageEl.style.transform = `scale(${scale})`;
  shell.style.width = (naturalW*scale)+'px';
  shell.style.height = (naturalH*scale)+'px';
  el(labelId).textContent = `weergave ${Math.round(scale*100)}% — print altijd op 100%`;
}

// Re-fit both previews once the gate unlocks and the app actually becomes
// visible (its layout — and container.clientWidth — didn't exist before this).
function refitAllPreviews(){
  if(typeof fitPreview !== 'function') return;
  try {
    fitPreview('pageO','pageShellO','scaleLabelO');
    fitPreview('pageL','pageShellL','scaleLabelL');
  } catch(e){ /* elements not ready yet — ignored, resize listener will catch up */ }
}

function requestPrint(source){
  const evt = new CustomEvent('ac:print-request', { cancelable: true, detail: { source } });
  const handledByNativeShell = !window.dispatchEvent(evt);
  if(handledByNativeShell) return;
  if(typeof window.print === 'function'){
    window.print();
  } else {
    alert('Printen wordt niet ondersteund in deze omgeving.');
  }
}
window.AppliedConceptsPrint = requestPrint;

const MB_TRAIN_GROUP_TABS = ['dryfire','train','shottimer','dopecard'];
const MB_OPTIC_GROUP_TABS = ['optic','turret'];

function switchTab(tab){
  if(tab !== 'dryfire' && window.AppliedConceptsDryfire) window.AppliedConceptsDryfire.stopTimer();
  if(tab !== 'shottimer' && window.AppliedConceptsShottimer) window.AppliedConceptsShottimer.stopTimer();
  if(tab !== 'dopecard' && window.AppliedConceptsDopeCard) window.AppliedConceptsDopeCard.stopTimer();
  document.querySelectorAll('.tabbtn[data-tab]').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  document.querySelectorAll('.mb-item[data-tab]').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  el('mbTrainBtn').classList.toggle('active', MB_TRAIN_GROUP_TABS.includes(tab));
  el('mbOpticBtn').classList.toggle('active', MB_OPTIC_GROUP_TABS.includes(tab));
  el('panel-optic').classList.toggle('active', tab==='optic');
  el('panel-profiles').classList.toggle('active', tab==='profiles');
  el('panel-turret').classList.toggle('active', tab==='turret');
  el('panel-dryfire').classList.toggle('active', tab==='dryfire');
  el('panel-train').classList.toggle('active', tab==='train');
  el('panel-shottimer').classList.toggle('active', tab==='shottimer');
  el('panel-dopecard').classList.toggle('active', tab==='dopecard');
  el('panel-shop').classList.toggle('active', tab==='shop');
  el('panel-contact').classList.toggle('active', tab==='contact');
  if(tab==='optic') renderOptic();
  else if(tab==='profiles') window.AppliedConceptsProfiles.render();
  else if(tab==='turret') window.AppliedConceptsTurret.init();
  else if(tab==='dryfire') window.AppliedConceptsDryfire.render();
  else if(tab==='train') window.AppliedConceptsTrain.init();
  else if(tab==='shottimer') window.AppliedConceptsShottimer.init();
  else if(tab==='dopecard') window.AppliedConceptsDopeCard.init();
  else if(tab==='shop'){ window.AppliedConceptsShop.init(); window.AppliedConceptsShop.resetView(); }
  else if(tab==='contact') window.AppliedConceptsContact.init();
}

function initOptic(){
  el('sightO').innerHTML = SIGHTS.map((sVal,i)=>`<option value="${i}">${sVal.label}${sVal.hobIn?` — ${(sVal.hobIn*2.54).toFixed(1)} cm`:''}</option>`).join('');
  el('mountO').innerHTML = MOUNTS.map((m,i)=>`<option value="${i}">${m.label}${m.hobIn?` — ${(m.hobIn*2.54).toFixed(1)} cm`:''}</option>`).join('');
  el('sightO').value = 2;
  el('mountO').value = 2;

  populateSelect(el('zeroDistO'), OPTIC_DIST, d=>d+' m');
  populateSelect(el('workDistO'), OPTIC_DIST, d=>d+' m');
  el('zeroDistO').selectedIndex = 2;
  el('workDistO').selectedIndex = 0;
  refreshWorkDistOptions(OPTIC_DIST,'zeroDistO','workDistO');

  el('hobUnitO').value = 'cm';
  applyAutoHOB('O');

  // RMR/LPVO always go together in this setup: RMR sits piggyback on the
  // LPVO (so its montage is always the LPVO-riser), and LPVO is itself the
  // richtmiddel, normally mounted (no separate montage) — so picking one of
  // these two sights auto-selects the matching montage before the HOB
  // auto-fill runs, instead of leaving whatever montage happened to be
  // selected before.
  el('sightO').addEventListener('change', ()=>{
    const sight = SIGHTS[el('sightO').value];
    const mountSel = el('mountO');
    if(sight.id === 'lpvo') mountSel.value = MOUNTS.findIndex(m=>m.id==='none');
    else if(sight.id === 'rmr') mountSel.value = MOUNTS.findIndex(m=>m.id==='lpvo_riser');
    applyAutoHOB('O');
    renderOptic();
  });
  el('mountO').addEventListener('change', ()=>{ applyAutoHOB('O'); renderOptic(); });
  // Marks the field as "typed by the user", not auto-filled — see the
  // dataset.autofilled check in applyAutoHOB() below. Setting .value from
  // JS never fires a real 'input' event on its own, so this only reacts to
  // an actual keystroke, never to our own auto-fill.
  el('hobValueO').addEventListener('input', ()=>{ delete el('hobValueO').dataset.autofilled; });
  ['hobValueO','hobUnitO','clickValO','workDistO','paperSizeO','weaponLabelO'].forEach(id=>{
    el(id).addEventListener('input', renderOptic);
    el(id).addEventListener('change', renderOptic);
  });
  el('zeroDistO').addEventListener('change', ()=>{ refreshWorkDistOptions(OPTIC_DIST,'zeroDistO','workDistO'); renderOptic(); });
  el('adjUnitO').addEventListener('change', ()=>{ refreshClickOptions('adjUnitO','clickValO'); renderOptic(); });
  el('printBtnO').addEventListener('click', ()=>requestPrint('zero-optic-calculator'));
  window.addEventListener('resize', ()=>{ if(el('panel-optic').classList.contains('active')) fitPreview('pageO','pageShellO','scaleLabelO'); });

  el('platformO').addEventListener('change', ()=>{
    const preset = OPTIC_PLATFORMS[el('platformO').value];
    if(!preset){ renderOptic(); return; }
    if(!el('weaponLabelO').value) el('weaponLabelO').placeholder = preset.weaponLabel;
    renderOptic();
  });

  refreshClickOptions('adjUnitO','clickValO');
  renderOptic();
}

function applyAutoHOB(suffix){
  const sight = SIGHTS[el('sight'+suffix).value];
  const mount = MOUNTS[el('mount'+suffix).value];
  const hint = el('hobHint'+suffix);
  const src = el('hobSrc'+suffix);
  let hobIn = null, srcText = '';

  if(mount.id === 'manual_mount'){
    hint.textContent = 'Handmatige montage gekozen — vul zelf de gemeten hoogte in.';
    src.textContent = '';
    return;
  }
  if(mount.id !== 'none'){
    hobIn = mount.hobIn;
    srcText = mount.src;
    hint.textContent = `Bepaald door montage: ${mount.label}.`;
  } else {
    hobIn = sight.hobIn;
    srcText = sight.src;
    if(hobIn == null){
      hint.textContent = `Geen standaardwaarde voor ${sight.label} zonder montage — meet zelf de afstand tussen hart loop en hart richtmiddel.`;
    } else {
      hint.textContent = `Bepaald door richtmiddel-standaard: ${sight.label}.`;
    }
  }

  const hobValueEl = el('hobValue'+suffix);
  const hobUnitEl = el('hobUnit'+suffix);
  if(hobIn != null){
    hobValueEl.value = hobUnitEl.value === 'cm' ? (hobIn/CM_IN).toFixed(2) : hobIn;
    hobValueEl.dataset.autofilled = '1';
  } else if(!hobValueEl.value || hobValueEl.dataset.autofilled === '1'){
    // Clear a stale auto-filled number from a *previous* sight/mount combo
    // (e.g. RMR standalone -> LPVO-als-riser-voor-RMR-piggyback) — without
    // this, switching to a "no standard value, meet zelf" combo left the
    // old combo's number sitting there looking like a real answer instead
    // of the blank it should be. Never touches a value the user typed
    // themselves (dataset.autofilled only gets set by us, above).
    hobValueEl.value = '';
    delete hobValueEl.dataset.autofilled;
  }
  src.textContent = srcText ? 'Bron: ' + srcText : '';
}

function refreshClickOptions(adjId, clickId){
  const unit = el(adjId).value;
  populateSelect(el(clickId), CLICKS[unit], v=>`${v} ${unit}`);
  el(clickId).selectedIndex = 0;
}

function hobInches(suffix){
  const v = parseFloat(el('hobValue'+suffix).value) || 0;
  return el('hobUnit'+suffix).value === 'cm' ? v*CM_IN : v;
}

// Only available when a Wapenplatform preset is selected (see
// OPTIC_PLATFORM_AMMO) and a real HOB is filled in — without a known
// caliber/ammo there's nothing to simulate a trajectory from.
function computeOpticTrajectory(zeroDist, hobIn){
  const ammo = OPTIC_PLATFORM_AMMO[el('platformO').value];
  if(!ammo || !(hobIn > 0.03) || !window.AppliedConceptsBallistics) return null;
  return window.AppliedConceptsBallistics.computeTrajectoryProfile({
    dragModel: ammo.dragModel,
    bc: ammo.bc,
    muzzleVelocityFps: ammo.muzzleVelocityFps,
    sightHeightCm: hobIn / CM_IN,
    zeroDistanceM: zeroDist,
    bulletWeightGr: ammo.bulletWeightGr,
  });
}

function getStateOptic(){
  const unit = el('adjUnitO').value;
  const zeroDist = OPTIC_DIST[el('zeroDistO').value];
  let workDist = OPTIC_DIST[el('workDistO').value];
  if(workDist > zeroDist) workDist = zeroDist;
  const hobIn = hobInches('O');
  const hobDisplay = el('hobUnitO').value === 'cm' ? `${parseFloat(el('hobValueO').value||0).toFixed(2)} cm` : `${parseFloat(el('hobValueO').value||0).toFixed(2)}"`;
  const off = offsetAxis(hobIn, zeroDist, workDist);
  const showMarker = workDist < zeroDist && off > 0.03;
  // Distinguish "no offset because you're checking at the zero distance itself"
  // (expected, POI should sit on POA) from "no offset because HOB is 0/empty"
  // (you forgot to fill it in) — otherwise the same reassuring caption shows
  // in both cases and a missing HOB silently looks like a correct zero.
  const noMarkerCaption = (workDist < zeroDist && hobIn <= 0.03)
    ? 'Vul de height-over-bore in om de POI te tonen — nu op 0.'
    : 'Directe controle op nulpunt-afstand — POI hoort hier te vallen';
  const platformAmmo = OPTIC_PLATFORM_AMMO[el('platformO').value] || null;
  const trajectory = platformAmmo ? computeOpticTrajectory(zeroDist, hobIn) : null;
  // Explains an empty trajectory block instead of just silently omitting it —
  // a small HOB zeroed at a longer distance (e.g. a red dot at 100 m) often
  // has no 2nd crossing within practical range at all, which is correct
  // physics, not a bug, but looks broken without this note.
  let trajectoryNote = null;
  if(platformAmmo && !(hobIn > 0.03)) trajectoryNote = 'Vul de HOB in om de kogelbaan te berekenen.';
  else if(platformAmmo && !trajectory) trajectoryNote = 'Geen 2e kruispunt binnen bereik voor deze combinatie van nulpunt en HOB (vaak bij een klein HOB op een verder nulpunt, bv. een rooddot op 100 m).';
  return {
    paper: PAGE_DIMS[el('paperSizeO').value],
    paperKey: el('paperSizeO').value,
    titleMain: 'ZERO OPTIC CALCULATOR',
    weaponLabel: el('weaponLabelO').value.trim(),
    metaRows: [
      [ `Richtmiddel: ${SIGHTS[el('sightO').value].label}`, `Montage: ${MOUNTS[el('mountO').value].label}` ],
      [ `HOB: ${hobDisplay} · Nulpunt: ${zeroDist} m · Controle: ${workDist} m`, null ],
    ],
    markers: [
      { offX:0, offY:off, label:'POI', show:showMarker,
        detail: `Bevestigt nulpunt op ${zeroDist} m — offset ${fmtLen(off,'cm')} (HOB ${hobDisplay})` },
    ],
    zeroDist, workDist, distUnit:'m',
    gridIn: 1*CM_IN,
    adjUnit: unit,
    clickVal: CLICKS[unit][el('clickValO').value],
    distOptions: OPTIC_DIST,
    sameDistanceCaption: noMarkerCaption,
    footerRight: 'Applied Concepts — Zero Optic Calculator',
    hobDisplay, off,
    trajectory, trajectoryCaliber: platformAmmo ? platformAmmo.caliber : null, trajectoryNote,
  };
}

function renderOptic(){
  const s = getStateOptic();
  el('pageO').style.width = s.paper.w + 'in';
  el('pageO').style.height = s.paper.h + 'in';
  const result = buildTargetSVG(s);
  el('pageO').innerHTML = result.svg;

  el('summaryBoxO').innerHTML = `
    <div class="row"><span>HOB</span><span>${s.hobDisplay}</span></div>
    <div class="row"><span>Nulpunt</span><span>${s.zeroDist} m</span></div>
    <div class="row"><span>Controle-afstand</span><span>${s.workDist} m</span></div>
    <div class="row"><span>Mech. offset</span><span>${s.off>0.03? fmtLen(s.off,'cm') : '≈ 0 (zelfde punt)'}</span></div>
    ${s.trajectory ? `
    <div class="row"><span>1e kruispunt (inschiet)</span><span>${s.trajectory.nearZeroM} m</span></div>
    <div class="row"><span>2e kruispunt</span><span>${s.trajectory.farZeroM.toFixed(0)} m</span></div>
    <div class="row"><span>Drop @ +100 m na 2e kruispunt</span><span>${s.trajectory.dropCm.toFixed(0)} cm</span></div>
    <div class="row"><span>Energie op die afstand</span><span>${s.trajectory.energyJAtTarget.toFixed(0)} J (${s.trajectory.energyFtLbsAtTarget.toFixed(0)} ft-lbs)</span></div>
    ` : (s.trajectoryNote ? `<p class="hint">${s.trajectoryNote}</p>` : '')}
  `;

  const warn = el('fitWarningO');
  if(s.workDist < s.zeroDist && s.off>0.03 && !result.fitsOnPage){
    warn.innerHTML = `<p class="warn">De berekende offset (${fmtLen(s.off,'cm')}) past niet meer binnen ${s.paper.label} op deze indeling. Kies Letter, een grotere controleafstand, of verhoog de nulpunt-afstand.</p>`;
  } else {
    warn.innerHTML = '';
  }

  const advice = el('paperAdviceO');
  advice.textContent = s.paperKey==='a4'
    ? 'A4 is 6% smaller dan Letter. Bij grote HOB (bv. GBRS Hydra) met een korte controleafstand kan de referentie-box krap komen — check de waarschuwing hierboven.'
    : 'Letter is gangbaar bij Amerikaanse optiek-fabrikanten en geeft iets meer ruimte voor grote offsets.';

  fitPreview('pageO','pageShellO','scaleLabelO');
}

document.querySelectorAll('.tabbtn[data-tab]').forEach(btn=>{
  btn.addEventListener('click', ()=>switchTab(btn.dataset.tab));
});

/* ---------------------------------------------------------------------
   Mobile bottom tab bar (< 760px, see css/styles.css) — 5 direct
   destinations (Optic/Profielen/Train/Shop/Contact), all visible at once
   with no horizontal scrolling. "Optic" and "Train" each open a small
   bottom sheet to choose between their two grouped tabs (Zero Calc./
   Turret Tape, and Dry Fire/Train) — fewer icons in the bar itself for a
   calmer, less cluttered look.
--------------------------------------------------------------------- */
document.querySelectorAll('.mb-item[data-tab]').forEach(btn=>{
  btn.addEventListener('click', ()=>switchTab(btn.dataset.tab));
});

function openSheet(sheet){ sheet.hidden = false; }
function closeSheet(sheet){ sheet.hidden = true; }

el('mbTrainBtn').addEventListener('click', ()=>openSheet(el('moreSheet')));
el('moreSheetScrim').addEventListener('click', ()=>closeSheet(el('moreSheet')));
el('mbOpticBtn').addEventListener('click', ()=>openSheet(el('opticSheet')));
el('opticSheetScrim').addEventListener('click', ()=>closeSheet(el('opticSheet')));
document.querySelectorAll('.more-sheet-item[data-tab]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    switchTab(btn.dataset.tab);
    closeSheet(btn.closest('.more-sheet'));
  });
});

/* ---------------------------------------------------------------------
   "Installeer deze app" popup. Chrome/Android/Edge fire beforeinstallprompt
   when the PWA criteria are met and expose a native prompt() we can trigger
   from our own button; iOS Safari and desktop Safari have no such event or
   prompt at all — the only path there is Share ▸ Zet op beginscherm/Zet in
   Dock, so those cases get static instructions instead of a button.
   Skipped entirely once already installed (standalone display mode).

   No dismiss-persistence at all, ON PURPOSE (explicit choice, 18-09-2026):
   the popup shows every time this init runs, i.e. every fresh page load.
   Closing it only hides it for the current view. This lines up with the
   pass phrase gate, which is also never remembered — every time someone
   has to re-enter the pass phrase, they see the popup again too. Revisit
   once the feature is settled: the plan is to eventually make it "gone for
   good once the app is actually installed" (gate on isStandalone alone).
--------------------------------------------------------------------- */
function initInstallBanner(){
  const banner = document.getElementById('installBanner');
  if(!banner) return;

  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  if(isStandalone) return;

  const closeBtn = document.getElementById('installBannerClose');
  const dismiss = () => { banner.hidden = true; };
  closeBtn.addEventListener('click', dismiss);
  banner.addEventListener('click', (e)=>{ if(e.target === banner) dismiss(); });

  const ua = navigator.userAgent;
  const isIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
  if(isIOS){
    document.getElementById('installBannerText').textContent =
      'Installeer deze app: tik op het deel-icoon onderin Safari en kies "Zet op beginscherm".';
    banner.hidden = false;
    return;
  }

  // Desktop Safari (macOS) never fires beforeinstallprompt either — like
  // iOS, it needs its own static instructions ("Zet in Dock", Safari 17+ /
  // macOS Sonoma+) instead of silently showing nothing, which is what a
  // Mac visitor saw before this branch existed.
  const isSafari = /^((?!chrome|android).)*safari/i.test(ua);
  if(isSafari){
    document.getElementById('installBannerText').textContent =
      'Installeer deze app: klik in Safari op het deel-icoon (of het Archief-menu) en kies "Zet in Dock".';
    banner.hidden = false;
    return;
  }

  // Everything else (Chrome/Edge/Brave/Android, etc.): wait for the
  // browser's own installability signal instead of assuming support —
  // desktop Firefox never fires this event, and showing a broken
  // "Installeren" button there would be worse than showing nothing.
  let deferredPrompt = null;
  window.addEventListener('beforeinstallprompt', (e)=>{
    e.preventDefault();
    deferredPrompt = e;
    document.getElementById('installBannerText').textContent =
      'Installeer deze app op je toestel voor snelle toegang, ook offline.';
    const installBtn = document.getElementById('installBannerBtn');
    installBtn.hidden = false;
    installBtn.addEventListener('click', async ()=>{
      if(!deferredPrompt) return;
      installBtn.disabled = true;
      deferredPrompt.prompt();
      await deferredPrompt.userChoice;
      deferredPrompt = null;
      dismiss();
    });
    banner.hidden = false;
  });
}

